WITH prev_events AS (SELECT *, LAG(event_time) OVER (PARTITION BY page ORDER BY event_time ASC, id ASC) AS prev_event_time FROM web_events), gaps AS (SELECT *, CASE WHEN prev_event_time IS NULL OR event_time > prev_event_time + INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_session FROM prev_events), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY page ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT DATE_TRUNC('WEEK', prev_event_time) AS week_start, CASE WHEN session_no >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END AS session_no_tier, ROUND(AVG(is_new_session), 2) AS avg_is_new_session, COUNT(CASE WHEN event_type = 'purchase' THEN 1 END) AS purchase_count, COUNT(*) AS event_count, SIZE(COLLECT_SET(page)) AS num_pages, GROUPING_ID() AS grouping_id FROM sessionized GROUP BY ROLLUP (DATE_TRUNC('WEEK', prev_event_time), CASE WHEN session_no >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END) ORDER BY session_no_tier ASC
